Add Redux. Redux manage state. State: menu items, cart.

1. **Install Redux**: `npm install redux react-redux` or `yarn add redux react-redux`.
2. **Create Store**: `store.js`. Import `createStore` from `redux`. Define reducer. Initial state: empty cart, menu items from API or static data.
```javascript
// store.js
import { createStore } from 'redux';

const initialState = {
  cart: [],
  menu: [
    { id: 1, name: 'Burger', price: 10.99 },
    { id: 2, name: 'Fries', price: 4.99 },
    // ...
  ],
};

const reducer = (state = initialState, action) => {
  switch (action.type) {
    case 'ADD_TO_CART':
      return { ...state, cart: [...state.cart, action.item] };
    case 'REMOVE_FROM_CART':
      return { ...state, cart: state.cart.filter(item => item.id !== action.item.id) };
    default:
      return state;
  }
};

const store = createStore(reducer);

export default store;
```
3. **Wrap App**: `index.js`. Import `Provider` from `react-redux`. Wrap app with `Provider`, pass `store`.
```javascript
// index.js
import React from 'react';
import ReactDOM from 'react-dom';
import App from './App';
import store from './store';
import { Provider } from 'react-redux';

ReactDOM.render(
  <Provider store={store}>
    <App />
  </Provider>,
  document.getElementById('root')
);
```
